def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path

    components = split(path)
    stack = []
    link_count = 0

    while components:
        comp = components.pop(0)
        if comp == '..':
            if stack:
                stack.pop()
            continue
        stack.append(comp)
        current = '/' + '/'.join(stack)
        if current in links:
            link_count += 1
            if link_count > 8:
                return None
            target = links[current]
            if not target.startswith('/'):
                dir_path = '/' + '/'.join(stack[:-1])
                if dir_path == '/':
                    target = '/' + target
                else:
                    target = dir_path + '/' + target
            stack.pop()  # remove the link's own name from resolved stack
            target_components = split(target)
            components = target_components + components

    if not stack:
        return '/'
    return '/' + '/'.join(stack)

